import customers from './customers.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'customer_lookup',
      description: 'Look up a customer by their unique customer id and return their directory record.',
      inputSchema: {
        type: 'object',
        properties: {
          customer_id: {
            type: 'string',
            description: 'The unique identifier of the customer to look up.',
          },
        },
        required: ['customer_id'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'customer_lookup') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  const allowed = new Set(['customer_id']);
  const extra = Object.keys(args).filter((k) => !allowed.has(k));
  if (extra.length > 0) {
    throw new Error(`Invalid arguments: unexpected properties ${extra.join(', ')}`);
  }

  const { customer_id } = args;

  if (typeof customer_id !== 'string') {
    throw new Error('Invalid arguments: customer_id must be a string');
  }

  const record = customers[customer_id];
  if (!record) {
    throw new Error(`Unknown customer: ${customer_id}`);
  }

  return {
    content: [
      {
        type: 'text',
        text: `${record.name} (${record.tier})`,
      },
    ],
  };
}

